<?php
declare(strict_types=1);
require_once __DIR__.'/../app/bootstrap.php';
$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT a.*,n.name antenna_name FROM articles a JOIN antennas n ON n.id=a.antenna_id WHERE a.id=? AND a.is_deleted=0 LIMIT 1');$s->execute([$id]);$a=$s->fetch();if(!$a){http_response_code(410);echo '<!doctype html><meta charset="utf-8"><title>410</title><h1>この記事は利用できません</h1>';exit;}$ua=hash('sha256',(string)($_SERVER['HTTP_USER_AGENT']??''));$ref=parse_url((string)($_SERVER['HTTP_REFERER']??''),PHP_URL_HOST)?:null;db()->prepare("INSERT INTO access_events(antenna_id,article_id,event_type,ref_host,ip_hash,ua_hash,created_at) VALUES(?,?,'pv',?,?,?,NOW())")->execute([(int)$a['antenna_id'],$id,$ref,client_ip_hash(),$ua]);if(isset($_GET['go'])){db()->prepare("INSERT INTO access_events(antenna_id,article_id,event_type,ref_host,ip_hash,ua_hash,created_at) VALUES(?,?,'out',NULL,?,?,NOW())")->execute([(int)$a['antenna_id'],$id,client_ip_hash(),$ua]);header('Location: '.$a['url'],true,302);exit;}
?><!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($a['title'])?> | <?=e($a['antenna_name'])?></title><link rel="canonical" href="<?=e(base_url('public/relay.php?id='.$id))?>"></head><body><main><nav><a href="/">トップ</a> &gt; 記事</nav><h1><?=e($a['title'])?></h1><p><a href="?id=<?=$id?>&go=1" style="font-weight:700;color:#c00"><?=e($a['title'])?></a></p></main></body></html>
